import { defineConfig } from 'vite'
import { readdirSync, statSync } from 'node:fs'
import { join, relative } from 'node:path'

/**
 * Multi-page build: every .html file in the repo (except dist/ and node_modules/)
 * becomes its own entry, so /work/ and /writing/<slug>/ ship as real static pages.
 * The post pages under writing/ are generated by scripts/gen-posts.mjs before Vite runs.
 */
function htmlInputs(dir: string, base = dir): Record<string, string> {
  const skip = new Set(['node_modules', 'dist', 'public', 'deploy', 'scripts', 'src'])
  const out: Record<string, string> = {}
  for (const entry of readdirSync(dir)) {
    if (skip.has(entry) || entry.startsWith('.')) continue
    const full = join(dir, entry)
    if (statSync(full).isDirectory()) Object.assign(out, htmlInputs(full, base))
    else if (entry.endsWith('.html')) out[relative(base, full).replace(/\.html$/, '') || 'index'] = full
  }
  return out
}

export default defineConfig({
  build: {
    target: 'es2022',
    rollupOptions: { input: htmlInputs('.') },
    assetsInlineLimit: 2048,
  },
  server: { port: 5173, strictPort: false },
})
